findings.codeql_raw_query:
/**
 * @name YAML constructor unsafe tag execution
 * @description YAML constructors with Python tags can execute arbitrary code
 * @kind path-problem
 * @problem.severity error
 * @id py/yaml-constructor-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module YAMLConstructorConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for calls to python object constructors or eval-like functions
    // in YAML constructors when processing tags
    sink = any(CodeExecution ce).getCode() 
    or
    exists(API::CallNode call |
      call = API::builtin(["eval", "exec", "__import__"]).getACall()
      and sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember(["Popen", "call", "run"]).getACall()
      and sink = call.getArg(0)
    )
  }
}

module YAMLConstructorFlow = TaintTracking::Global<YAMLConstructorConfig>;
import YAMLConstructorFlow::PathGraph

from YAMLConstructorFlow::PathNode source, YAMLConstructorFlow::PathNode sink
where YAMLConstructorFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential code injection in YAML constructor from $@.", source.getNode(), "user input"
